package com.example.Email.Controller;import com.example.Email.DTO.Request.LinkEmailToCrmRequest;import com.example.Email.DTO.Response.EmailCrmLinkResponse;import com.example.Email.Service.EmailCrmLinkService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class EmailCrmLinkController {private final EmailCrmLinkService service;@PostMapping("/emails/{messageId}/crm-links") public ResponseEntity<EmailCrmLinkResponse> link(@PathVariable Long messageId,@Valid @RequestBody LinkEmailToCrmRequest r){return ResponseEntity.status(201).body(service.link(messageId,r));}@GetMapping("/crm/{entityType}/{entityId}/emails") public List<EmailCrmLinkResponse> emails(@PathVariable String entityType,@PathVariable String entityId){return service.forEntity(entityType,entityId);}}
